// src/facets/footsteps.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
use super::World;
use genex::prelude::*;

#[derive(Default)]
pub struct Footsteps { step: Option<Sound>, theme: Option<Music>, steps: u32, refused: bool }

pub fn wire(game: &mut Game<World>) {
    game.facet_state::<Footsteps>();
    game.on_reset(|sim, _, _, gfx| {
        let feet = sim.facets.get_mut::<Footsteps>();
        let step = gfx.sound("sfx/step.wav");
        // A refused file is a missing handle: step.refusal() says why, volatile.audio.issues lists it.
        feet.refused = step.is_missing();
        feet.step = Some(step);
        feet.theme = Some(gfx.music("music/theme.ogg"));
    });
    game.on_update(|sim, ctx| {
        let at = sim.world.player;
        let feet = sim.facets.get_mut::<Footsteps>();
        if ctx.tick == 1
            && let Some(theme) = &feet.theme
        {
            ctx.audio.music(theme, MusicOpts::default()); // loops, crossfading from what plays
        }
        let Some(step) = &feet.step else { return };
        if ctx.tick % 20 == 0 && ctx.keys.down(Key::KeyW) {
            ctx.audio.play_at(step, at); // decided in the tick, the same on every destination
            feet.steps += 1;
        }
    });
    game.probe("steps", |sim| {
        let feet = sim.facets.get::<Footsteps>();
        json!({ "steps": feet.steps, "refused": feet.refused })
    });
}
